mkfn!{
    rsplit_file_at_dot_introspect!();
    fn rsplit_file_at_dot (file : & OsStr) -> (Option < & OsStr > , Option < & OsStr >) { if file . as_encoded_bytes () == b".." { return (Some (file) , None) ; } let mut iter = file . as_encoded_bytes () . rsplitn (2 , | b | * b == b'.') ; let after = iter . next () ; let before = iter . next () ; if before == Some (b"") { (Some (file) , None) } else { unsafe { (before . map (| s | OsStr :: from_encoded_bytes_unchecked (s)) , after . map (| s | OsStr :: from_encoded_bytes_unchecked (s)) ,) } } }
}

macro_rules! split_file_at_dot_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function split_file_at_dot in module {}", module_path!());
    };
}

mkfn!{
    split_file_at_dot_introspect!();
    fn split_file_at_dot (file : & OsStr) -> (& OsStr , Option < & OsStr >) { let slice = file . as_encoded_bytes () ; if slice == b".." { return (file , None) ; } let i = match slice [1 ..] . iter () . position (| b | * b == b'.') { Some (i) => i + 1 , None => return (file , None) , } ; let before = & slice [.. i] ; let after = & slice [i + 1 ..] ; unsafe { (OsStr :: from_encoded_bytes_unchecked (before) , Some (OsStr :: from_encoded_bytes_unchecked (after)) ,) } }
}

